-- ----- 20261009000100_schema.sql -----
-- Contest Scoreboard: schema, helper functions, guard + audit triggers.
-- Security (RLS, grants, storage) is in 20261009000300_security.sql.

create extension if not exists citext with schema public;

-- ---------------------------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------------------------
create type contest_status as enum ('setup', 'open', 'closed', 'final', 'archived');
create type submission_status as enum ('draft', 'pending', 'approved', 'rejected', 'withdrawn', 'reversed');
create type admin_role as enum ('owner', 'admin');
create type actor_type as enum ('member', 'admin', 'system');

-- ---------------------------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------------------------
create table contests (
  id                 uuid primary key default gen_random_uuid(),
  name               text not null,
  start_at           timestamptz not null,
  end_at             timestamptz not null,
  grace_minutes      int not null default 10 check (grace_minutes >= 0),
  -- only setup / final / archived are ever stored; open + closed are derived from time
  manual_status      contest_status not null default 'setup'
                       check (manual_status in ('setup', 'final', 'archived')),
  points_unlocked    boolean not null default false,
  finalized_at       timestamptz,
  results_updated_at timestamptz,
  exported_at        timestamptz,  -- set by contest-export; archive requires it
  created_at         timestamptz not null default now(),
  check (end_at > start_at)
);

create table members (
  id            uuid primary key references auth.users (id),
  contest_id    uuid not null references contests (id),
  email         citext not null,
  display_name  text not null check (char_length(btrim(display_name)) between 1 and 60),
  key_version   int not null default 1,
  active        boolean not null default true,
  registered_at timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (contest_id, email)
);
create unique index members_display_name_uq on members (contest_id, lower(display_name));

create table admins (
  id         uuid primary key references auth.users (id),
  email      citext not null unique,
  role       admin_role not null,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

create table categories (
  id              uuid primary key default gen_random_uuid(),
  contest_id      uuid not null references contests (id),
  name            text not null check (char_length(btrim(name)) > 0),
  points          int not null check (points > 0),
  reference_label text not null,
  reference_hint  text not null default '',
  active          boolean not null default true,
  sort_order      int not null default 0
);

create table submissions (
  id                   uuid primary key default gen_random_uuid(),
  contest_id           uuid not null references contests (id),
  member_id            uuid not null references members (id),
  category_id          uuid not null references categories (id),
  reference            text not null,
  reference_normalized text not null,
  note                 text check (char_length(note) <= 280),
  proof_path           text not null,
  proof_hash           text,
  status               submission_status not null default 'draft',
  attempt              int not null default 1 check (attempt >= 1),
  resubmission_of      uuid references submissions (id),
  override_granted     boolean not null default false,
  flags                text[] not null default '{}',
  points_awarded       int,
  reject_reason_code   text,
  reject_reason_text   text,
  claimed_by           uuid,
  claimed_until        timestamptz,
  reviewed_by          uuid,
  reviewed_at          timestamptz,
  created_at           timestamptz not null default now(),
  submitted_at         timestamptz,
  check (status <> 'approved' or points_awarded is not null)
);

-- Same account / gig / message / order cannot be pending or approved twice, across all members.
create unique index submissions_reference_uq
  on submissions (contest_id, category_id, reference_normalized)
  where status in ('pending', 'approved');
-- One live resubmission per rejected submission. (Plan: status <> 'withdrawn'. Drafts are also
-- excluded so an abandoned upload never blocks the real attempt; the race is still closed at
-- confirm time because the first draft to become 'pending' takes the slot.)
create unique index submissions_resubmission_uq
  on submissions (resubmission_of)
  where resubmission_of is not null and status not in ('withdrawn', 'draft');
create index submissions_queue_idx on submissions (contest_id, status, submitted_at);
create index submissions_proof_hash_idx on submissions (proof_hash);
create index submissions_member_idx on submissions (member_id);

create table audit_log (
  id         bigserial primary key,
  contest_id uuid,
  actor_type actor_type not null,
  actor_id   uuid,
  action     text not null,
  entity     text not null,
  entity_id  uuid,
  before     jsonb,
  after      jsonb,
  reason     text,
  created_at timestamptz not null default now()
);
create index audit_log_contest_idx on audit_log (contest_id, created_at desc);
create index audit_log_entity_idx on audit_log (entity, entity_id);

-- Rate limiting for the resend-key flow (email + ip).
create table key_requests (
  id           bigserial primary key,
  email        citext not null,
  ip           text,
  requested_at timestamptz not null default now()
);
create index key_requests_email_idx on key_requests (email, requested_at);
create index key_requests_ip_idx on key_requests (ip, requested_at);

-- Used by the (optional) password verification hook for login lockout.
create table login_attempts (
  id           bigserial primary key,
  user_id      uuid not null,
  attempted_at timestamptz not null default now()
);
create index login_attempts_user_idx on login_attempts (user_id, attempted_at);

-- ---------------------------------------------------------------------------------------------
-- Helper functions
-- ---------------------------------------------------------------------------------------------
-- The "current" contest is the most recently created one (the UI only ever shows one).
create function current_contest_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select id from contests order by created_at desc limit 1
$$;

create function contest_effective_status(p_contest uuid) returns contest_status
language sql stable security definer set search_path = public, pg_temp as $$
  select case
    when c.manual_status in ('final', 'archived') then c.manual_status
    when now() < c.start_at then 'setup'::contest_status
    when now() < c.end_at then 'open'::contest_status
    else 'closed'::contest_status
  end
  from contests c where c.id = p_contest
$$;

create function is_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from admins a where a.id = auth.uid() and a.active)
$$;

create function is_owner() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (select 1 from admins a where a.id = auth.uid() and a.active and a.role = 'owner')
$$;

-- Active member of the current contest.
create function is_member() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from members m
    where m.id = auth.uid() and m.active and m.contest_id = current_contest_id()
  )
$$;

-- lowercase, trim, collapse whitespace, strip one leading @ or #
create function normalize_reference(p text) returns text
language sql immutable set search_path = pg_catalog as $$
  select btrim(regexp_replace(regexp_replace(lower(btrim(coalesce(p, ''))), '\s+', ' ', 'g'), '^[@#]', ''))
$$;

-- Sets audit context for the current transaction. Always called by RPCs so stale values from an
-- earlier statement in the same transaction can never leak into an audit row.
create function _audit_ctx(p_action text, p_reason text) returns void
language sql set search_path = pg_catalog as $$
  select set_config('app.action', coalesce(p_action, ''), true),
         set_config('app.reason', coalesce(p_reason, ''), true)
$$;

-- ---------------------------------------------------------------------------------------------
-- Row-shaping triggers
-- ---------------------------------------------------------------------------------------------
create function trg_submissions_normalize() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  new.reference := btrim(new.reference);
  new.reference_normalized := normalize_reference(new.reference);
  if new.reference_normalized = '' then
    raise exception 'reference_required: Reference is required.';
  end if;
  if char_length(new.reference) > 200 then
    raise exception 'reference_too_long: Reference is too long.';
  end if;
  return new;
end $$;
create trigger submissions_normalize before insert or update of reference on submissions
  for each row execute function trg_submissions_normalize();

create function trg_touch_updated_at() returns trigger
language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
create trigger members_touch before update on members
  for each row execute function trg_touch_updated_at();

-- Admin emails cannot register as members, and vice versa.
create function trg_member_admin_email() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if tg_table_name = 'members' and exists (select 1 from admins where email = new.email) then
    raise exception 'admin_email: This email belongs to an admin and cannot register as a member.';
  end if;
  if tg_table_name = 'admins' and exists (select 1 from members where email = new.email) then
    raise exception 'member_email: This email is already registered as a member.';
  end if;
  return new;
end $$;
create trigger members_not_admin before insert or update of email on members
  for each row execute function trg_member_admin_email();
create trigger admins_not_member before insert or update of email on admins
  for each row execute function trg_member_admin_email();

-- ---------------------------------------------------------------------------------------------
-- Guard triggers
-- ---------------------------------------------------------------------------------------------
-- Deadline: while the contest is open, end_at may only increase.
create function trg_guard_contest() returns trigger
language plpgsql set search_path = public, pg_temp as $$
begin
  if contest_effective_status(old.id) = 'open' and new.end_at < old.end_at then
    raise exception 'deadline_shorten: The deadline can only be extended while the contest is open.';
  end if;
  return new;
end $$;
create trigger contests_guard before update on contests
  for each row execute function trg_guard_contest();

-- Points lock + freeze + category deletion.
create function trg_guard_category() returns trigger
language plpgsql set search_path = public, pg_temp as $$
declare
  v_contest uuid := coalesce(new.contest_id, old.contest_id);
  v_status contest_status := contest_effective_status(v_contest);
begin
  if v_status in ('final', 'archived') then
    raise exception 'contest_frozen: The contest is final; categories cannot change.';
  end if;
  if tg_op = 'UPDATE' and new.points <> old.points
     and v_status <> 'setup'
     and not (select points_unlocked from contests where id = v_contest) then
    raise exception 'points_locked: Point values are locked once the contest starts.';
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from submissions where category_id = old.id) then
      raise exception 'category_in_use: Category has submissions; deactivate it instead.';
    end if;
    return old;
  end if;
  return new;
end $$;
create trigger categories_guard before insert or update or delete on categories
  for each row execute function trg_guard_category();

-- Freeze: nothing on submissions changes once final/archived (stale drafts may still be cleaned up).
create function trg_guard_submission() returns trigger
language plpgsql set search_path = public, pg_temp as $$
declare
  v_contest uuid := coalesce(new.contest_id, old.contest_id);
begin
  if contest_effective_status(v_contest) in ('final', 'archived')
     and not (tg_op = 'DELETE' and old.status = 'draft') then
    raise exception 'contest_frozen: The contest is final; submissions cannot change.';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
create trigger submissions_guard before insert or update or delete on submissions
  for each row execute function trg_guard_submission();

-- ---------------------------------------------------------------------------------------------
-- Audit log
-- ---------------------------------------------------------------------------------------------
create function trg_audit() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  v_row jsonb := coalesce(v_new, v_old);
  v_uid uuid := auth.uid();
  v_actor actor_type;
  v_noun text;
  v_action text;
  v_contest uuid;
begin
  if tg_table_name = 'submissions' then
    -- drafts are scratch space (created/deleted constantly); they are not state changes
    if coalesce(v_old ->> 'status', 'draft') = 'draft' and coalesce(v_new ->> 'status', 'draft') = 'draft' then
      return null;
    end if;
    -- admin claim/hold refreshes are not state changes either
    if tg_op = 'UPDATE' and (v_old - 'claimed_by' - 'claimed_until') = (v_new - 'claimed_by' - 'claimed_until') then
      return null;
    end if;
  end if;
  if tg_op = 'UPDATE' and v_old = v_new then return null; end if;

  v_actor := case
    when v_uid is null then 'system'
    when exists (select 1 from admins where id = v_uid) then 'admin'
    when exists (select 1 from members where id = v_uid) then 'member'
    else 'system' end;

  v_noun := case tg_table_name
    when 'contests' then 'contest' when 'members' then 'member' when 'admins' then 'admin'
    when 'categories' then 'category' else 'submission' end;

  v_action := coalesce(
    nullif(current_setting('app.action', true), ''),
    case when tg_table_name = 'submissions' and tg_op = 'UPDATE' and v_old ->> 'status' <> v_new ->> 'status'
         then 'submission.' || (v_new ->> 'status') end,
    v_noun || '.' || lower(tg_op));

  v_contest := case tg_table_name
    when 'contests' then (v_row ->> 'id')::uuid
    when 'admins' then current_contest_id()
    else (v_row ->> 'contest_id')::uuid end;

  insert into audit_log (contest_id, actor_type, actor_id, action, entity, entity_id, before, after, reason)
  values (v_contest, v_actor, v_uid, v_action, tg_table_name, (v_row ->> 'id')::uuid,
          v_old, v_new, nullif(current_setting('app.reason', true), ''));
  return null;
end $$;

create trigger contests_audit after insert or update or delete on contests
  for each row execute function trg_audit();
create trigger members_audit after insert or update or delete on members
  for each row execute function trg_audit();
create trigger admins_audit after insert or update or delete on admins
  for each row execute function trg_audit();
create trigger categories_audit after insert or update or delete on categories
  for each row execute function trg_audit();
create trigger submissions_audit after insert or update or delete on submissions
  for each row execute function trg_audit();

-- The audit log is append-only, even for the table owner / service role.
create function trg_audit_immutable() returns trigger
language plpgsql as $$
begin raise exception 'audit_immutable: The audit log is append-only.'; end $$;
create trigger audit_log_no_change before update or delete on audit_log
  for each row execute function trg_audit_immutable();
create trigger audit_log_no_truncate before truncate on audit_log
  for each statement execute function trg_audit_immutable();

-- ----- 20261009000700_multi_org.sql -----
-- Multi-tenant organization support: each organisation has its own admins, contests, and members.
-- This keeps a single-site install working by assigning all legacy rows to a default org.

create table organizations (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(btrim(name)) between 1 and 120),
  slug       citext not null unique check (char_length(btrim(slug)) between 2 and 60),
  created_at timestamptz not null default now()
);
create unique index organizations_slug_lower_uq on organizations (lower(slug));

create table platform_admins (
  id         uuid primary key references auth.users (id),
  email      citext not null unique,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

alter table contests add column if not exists organization_id uuid;
alter table members add column if not exists organization_id uuid;
alter table admins add column if not exists organization_id uuid;
alter table categories add column if not exists organization_id uuid;
alter table submissions add column if not exists organization_id uuid;
alter table audit_log add column if not exists organization_id uuid;
alter table key_requests add column if not exists organization_id uuid;

-- Backfilling tenant IDs is a schema transition, not a user change. Avoid synthetic audit
-- events and let historical records migrate even when their contest is already frozen.
alter table contests disable trigger contests_audit;
alter table members disable trigger members_touch;
alter table members disable trigger members_audit;
alter table admins disable trigger admins_audit;
alter table categories disable trigger categories_guard;
alter table categories disable trigger categories_audit;
alter table submissions disable trigger submissions_guard;
alter table submissions disable trigger submissions_audit;
alter table audit_log disable trigger audit_log_no_change;

with default_org as (
  insert into organizations (name, slug)
  select 'Default organization', 'default'
  where not exists (select 1 from organizations)
  returning id
)
update contests c
set organization_id = coalesce(c.organization_id, d.id)
from default_org d
where c.organization_id is null;

update members m
set organization_id = coalesce(m.organization_id, c.organization_id)
from contests c
where m.contest_id = c.id and m.organization_id is null;

update admins a
set organization_id = coalesce(a.organization_id, m.organization_id)
from members m
where a.id = m.id and a.organization_id is null;

update admins a
set organization_id = coalesce(a.organization_id, o.id)
from organizations o
where a.organization_id is null
and not exists (
  select 1 from members m where m.id = a.id
);

update categories cat
set organization_id = coalesce(cat.organization_id, c.organization_id)
from contests c
where cat.contest_id = c.id and cat.organization_id is null;

update submissions s
set organization_id = coalesce(s.organization_id, c.organization_id)
from contests c
where s.contest_id = c.id and s.organization_id is null;

update audit_log al
set organization_id = coalesce(
  al.organization_id,
  (select c.organization_id from contests c where c.id = al.contest_id),
  (select a.organization_id from admins a where a.id = al.actor_id),
  (select m.organization_id from members m where m.id = al.actor_id)
)
where al.organization_id is null;

update key_requests kr
set organization_id = (
  select c.organization_id
  from members m
  join contests c on c.id = m.contest_id
  where lower(m.email) = lower(kr.email)
  order by c.created_at desc
  limit 1
)
where kr.organization_id is null;

alter table contests enable trigger contests_audit;
alter table members enable trigger members_touch;
alter table members enable trigger members_audit;
alter table admins enable trigger admins_audit;
alter table categories enable trigger categories_guard;
alter table categories enable trigger categories_audit;
alter table submissions enable trigger submissions_guard;
alter table submissions enable trigger submissions_audit;
alter table audit_log enable trigger audit_log_no_change;

alter table contests alter column organization_id set not null;
alter table members alter column organization_id set not null;
alter table admins alter column organization_id set not null;
alter table categories alter column organization_id set not null;
alter table submissions alter column organization_id set not null;

alter table contests
  add constraint contests_organization_fkey foreign key (organization_id) references organizations (id) on delete cascade;

alter table members
  add constraint members_organization_fkey foreign key (organization_id) references organizations (id) on delete cascade;

alter table admins
  drop constraint if exists admins_email_key,
  add constraint admins_organization_fkey foreign key (organization_id) references organizations (id) on delete cascade,
  add constraint admins_org_email_uq unique (organization_id, email);

alter table categories
  add constraint categories_organization_fkey foreign key (organization_id) references organizations (id) on delete cascade;

alter table submissions
  add constraint submissions_organization_fkey foreign key (organization_id) references organizations (id) on delete cascade;

alter table audit_log
  add constraint audit_log_organization_fkey foreign key (organization_id) references organizations (id) on delete set null;

alter table key_requests
  add constraint key_requests_organization_fkey foreign key (organization_id) references organizations (id) on delete set null;

create index contests_organization_idx on contests (organization_id, created_at desc);
create index members_organization_idx on members (organization_id, contest_id, active);
create index admins_organization_idx on admins (organization_id, active, role);
create index categories_organization_idx on categories (organization_id, contest_id, active, sort_order);
create index submissions_organization_idx on submissions (organization_id, contest_id, status, submitted_at desc);
create index audit_log_organization_idx on audit_log (organization_id, contest_id, created_at desc);

create function current_organization_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(
    (select organization_id from admins where id = auth.uid() and active limit 1),
    (select organization_id from members where id = auth.uid() and active limit 1)
  )
$$;

create or replace function current_contest_id() returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id
  from contests c
  where c.organization_id = current_organization_id()
  order by c.created_at desc
  limit 1
$$;

create function current_contest_id(p_org_id uuid) returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select c.id
  from contests c
  where p_org_id = current_organization_id()
    and c.organization_id = p_org_id
  order by c.created_at desc
  limit 1
$$;

create function is_org_admin(p_org_id uuid default current_organization_id()) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1
    from admins a
    where a.id = auth.uid()
      and a.active
      and p_org_id = current_organization_id()
      and a.organization_id = p_org_id
  )
$$;

create function is_org_owner(p_org_id uuid default current_organization_id()) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1
    from admins a
    where a.id = auth.uid()
      and a.active
      and a.role = 'owner'
      and p_org_id = current_organization_id()
      and a.organization_id = p_org_id
  )
$$;

create or replace function is_admin() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from admins a
    where a.id = auth.uid()
      and a.active
      and a.organization_id = current_organization_id()
  )
$$;

create or replace function is_owner() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from admins a
    where a.id = auth.uid()
      and a.active
      and a.role = 'owner'
      and a.organization_id = current_organization_id()
  )
$$;

create or replace function is_member() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1
    from members m
    where m.id = auth.uid()
      and m.active
      and m.organization_id = current_organization_id()
      and m.contest_id = current_contest_id()
  )
$$;

revoke all on function current_organization_id() from public, anon, authenticated;
grant execute on function current_organization_id() to service_role, authenticated;
revoke all on function current_contest_id(uuid) from public, anon, authenticated;
grant execute on function current_contest_id(uuid) to service_role, authenticated;
revoke all on function is_org_admin(uuid) from public, anon, authenticated;
grant execute on function is_org_admin(uuid) to service_role, authenticated;
revoke all on function is_org_owner(uuid) from public, anon, authenticated;
grant execute on function is_org_owner(uuid) to service_role, authenticated;
revoke all on function is_admin() from public, anon, authenticated;
grant execute on function is_admin() to service_role, authenticated;
revoke all on function is_owner() from public, anon, authenticated;
grant execute on function is_owner() to service_role, authenticated;
revoke all on function is_member() from public, anon, authenticated;
grant execute on function is_member() to service_role, authenticated;

